"""Bounded, credential-safe HTTP access to the FRED and ALFRED API."""

from __future__ import annotations

import http.client
import json
import math
import os
import random
import re
import threading
import time
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass
from datetime import UTC, datetime
from email.utils import parsedate_to_datetime
from typing import Any

import pyarrow as pa
from vgi.catalog import SecretTypeSpec

SECRET_TYPE = "fred_api"
API_SECRET_TYPE = SecretTypeSpec(
    name=SECRET_TYPE,
    description="FRED API key, shared by FRED and ALFRED queries.",
    schema=pa.schema(
        [pa.field("api_key", pa.string(), metadata={"redact": "true", "vgi_doc": "Your FRED API key."})],
        metadata={"vgi_doc_url": "https://fred.stlouisfed.org/docs/api/api_key.html"},
    ),
)
_RATE_LOCK = threading.Lock()
_LAST_REQUEST = 0.0


class FredError(RuntimeError):
    """A safe error message suitable for returning through SQL."""


def _number(name: str, default: float, minimum: float, maximum: float) -> float:
    """Read and validate an operator-controlled numeric setting."""
    try:
        value = float(os.environ.get(name, str(default)))
    except ValueError:
        raise FredError(f"{name} must be numeric") from None
    if not math.isfinite(value) or not minimum <= value <= maximum:
        raise FredError(f"{name} must be between {minimum} and {maximum}")
    return value


@dataclass(frozen=True)
class Config:
    """Operator settings; neither credentials nor configuration enter stream state."""

    base_url: str = "https://api.stlouisfed.org/fred"
    timeout: float = 30.0
    attempts: int = 4
    retry_budget: float = 120.0
    min_interval: float = 0.55
    max_response_bytes: int = 16 * 1024 * 1024

    @classmethod
    def from_env(cls) -> Config:
        """Load settings, allowing plaintext HTTP only for explicitly enabled loopback tests."""
        url = os.environ.get("FRED_API_BASE_URL", cls.base_url).rstrip("/")
        try:
            parts = urllib.parse.urlsplit(url)
            valid_port = parts.port is None or 0 < parts.port <= 65535
        except ValueError:
            raise FredError("FRED_API_BASE_URL is invalid") from None
        loopback_http = (
            parts.scheme == "http"
            and parts.hostname in {"localhost", "127.0.0.1", "::1"}
            and os.environ.get("FRED_ALLOW_INSECURE_HTTP") == "1"
        )
        if (
            not parts.hostname
            or not valid_port
            or parts.username is not None
            or parts.password is not None
            or parts.query
            or parts.fragment
            or any(c.isspace() for c in url)
            or (parts.scheme != "https" and not loopback_http)
        ):
            raise FredError("FRED_API_BASE_URL must be HTTPS without credentials, query, or fragment")
        attempts = _number("FRED_MAX_ATTEMPTS", 4, 1, 6)
        if not attempts.is_integer():
            raise FredError("FRED_MAX_ATTEMPTS must be an integer")
        return cls(
            base_url=url,
            timeout=_number("FRED_TIMEOUT_SECONDS", 30, 0.1, 120),
            attempts=int(attempts),
            retry_budget=_number("FRED_RETRY_BUDGET_SECONDS", 120, 1, 600),
            min_interval=_number("FRED_MIN_INTERVAL_SECONDS", 0.55, 0, 60),
            max_response_bytes=int(_number("FRED_MAX_RESPONSE_BYTES", 16 * 1024 * 1024, 1024, 64 * 1024 * 1024)),
        )


def validate_key(value: str | None) -> str:
    """Reject absent or malformed credentials without disclosing their value."""
    if not value:
        raise FredError("FRED API key required: create a fred_api secret or set FRED_API_KEY in the worker environment")
    if re.fullmatch(r"[a-z0-9]{32}", value) is None:
        raise FredError("FRED API key must contain 32 lowercase letters or digits")
    return value


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    """Never forward the API key to a redirect destination."""

    def redirect_request(
        self, req: Any, fp: Any, code: int, msg: str, headers: Any, newurl: str
    ) -> urllib.request.Request | None:
        return None


def _throttle(interval: float, deadline: float) -> None:
    """Space request starts across threads in this process, within the request budget."""
    global _LAST_REQUEST
    with _RATE_LOCK:
        now = time.monotonic()
        delay = max(0.0, _LAST_REQUEST + interval - now)
        if now + delay >= deadline:
            raise FredError("FRED request budget exhausted while waiting for the rate limiter")
        if delay:
            time.sleep(delay)
        _LAST_REQUEST = time.monotonic()


def retry_delay(header: str | None, attempt: int) -> float:
    """Honor delta-seconds or HTTP-date Retry-After; otherwise use jittered backoff."""
    if header:
        try:
            seconds = float(header)
            if math.isfinite(seconds) and seconds >= 0:
                return seconds
        except ValueError:
            try:
                when = parsedate_to_datetime(header)
                if when.tzinfo is None:
                    when = when.replace(tzinfo=UTC)
                return max(0.0, (when - datetime.now(UTC)).total_seconds())
            except (ValueError, TypeError, OverflowError):
                pass
    return float(min(16.0, 0.5 * 2**attempt) + random.uniform(0.0, 0.25))


def get_json(endpoint: str, params: dict[str, str | int], key: str, config: Config) -> dict[str, Any]:
    """Fetch one bounded JSON page with safe errors and budgeted retries."""
    key = validate_key(key)
    query = urllib.parse.urlencode({**params, "api_key": key, "file_type": "json"})
    request = urllib.request.Request(
        f"{config.base_url}/{endpoint}?{query}",
        headers={"Accept": "application/json", "User-Agent": "vgi-fred/0.1.0"},
    )
    opener = urllib.request.build_opener(_NoRedirect())
    deadline = time.monotonic() + config.retry_budget
    for attempt in range(config.attempts):
        _throttle(config.min_interval, deadline)
        delay = 0.0
        try:
            with opener.open(request, timeout=min(config.timeout, max(0.001, deadline - time.monotonic()))) as response:
                # Read incrementally to enforce the total deadline even when a server dribbles bytes.
                chunks: list[bytes] = []
                size = 0
                while True:
                    if time.monotonic() >= deadline:
                        raise FredError("FRED request exceeded its time budget")
                    chunk = response.read1(min(65536, config.max_response_bytes + 1 - size))
                    if not chunk:
                        break
                    chunks.append(chunk)
                    size += len(chunk)
                    if size > config.max_response_bytes:
                        raise FredError("FRED response exceeds FRED_MAX_RESPONSE_BYTES; reduce page_size")
                raw = b"".join(chunks)
            try:
                body = json.loads(raw)
            except (ValueError, UnicodeError):
                raise FredError(f"FRED {endpoint} returned invalid JSON") from None
            if not isinstance(body, dict) or "error_code" in body or "error_message" in body:
                raise FredError(f"FRED {endpoint} returned an invalid response or API error")
            return body
        except urllib.error.HTTPError as err:
            status = err.code
            header = err.headers.get("Retry-After")
            err.close()
            # Never echo upstream bodies, URLs or exception chains: FRED keys are query parameters.
            if not (status == 429 or 500 <= status <= 599) or attempt + 1 == config.attempts:
                hint = {
                    400: "check the API key, series identifier, and query parameters",
                    401: "check the API key",
                    403: "access denied",
                    404: "resource not found",
                    423: "resource locked",
                    429: "rate limit exceeded; reduce concurrency",
                }.get(status, "upstream request failed")
                raise FredError(f"FRED {endpoint} returned HTTP {status}: {hint}") from None
            delay = retry_delay(header, attempt)
        except (urllib.error.URLError, TimeoutError, OSError, http.client.HTTPException):
            if attempt + 1 == config.attempts:
                raise FredError(f"FRED {endpoint} network request failed after {config.attempts} attempts") from None
            delay = retry_delay(None, attempt)
        if time.monotonic() + delay >= deadline:
            raise FredError(f"FRED {endpoint} retry exceeds time budget; retry the query later")
        time.sleep(delay)
    raise AssertionError("unreachable")
